  }

  @protected
  void sse_encode_verdict_dto(VerdictDto self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case VerdictDto_Right():
        sse_encode_i_32(0, serializer);
      case VerdictDto_Almost(message: final message):
        sse_encode_i_32(1, serializer);
        sse_encode_String(message, serializer);
      case VerdictDto_Wrong():
        sse_encode_i_32(2, serializer);
      case VerdictDto_Unreadable(message: final message):
        sse_encode_i_32(3, serializer);
        sse_encode_String(message, serializer);
    }
  }

